-- metric_standard names without concept (excluding 3 rejected)
SELECT ms.name, ms.status, ms.chinese,
  (SELECT COUNT(*) FROM metric_column_binding b WHERE b.metric_name COLLATE utf8mb4_unicode_ci = ms.name AND b.is_active=1) AS bindings
FROM metric_standard ms
WHERE NOT EXISTS (SELECT 1 FROM metric_concept c WHERE c.concept_code COLLATE utf8mb4_unicode_ci = ms.name)
